[{"order":1,"type":"heading","text":"Advanced Django Database Migrations, Custom Operations, and Data Migrations"},{"order":2,"type":"paragraph","text":"Django migrations are a powerful tool for evolving your database schema over time. While basic migrations handle standard model creations and field additions, complex applications often require custom schema operations and safe handling of existing data. This tutorial explores how to build custom migration operations and write robust data migrations in Django."},{"order":3,"type":"subheading","text":"Understanding Django Migration Internals"},{"order":4,"type":"paragraph","text":"At its core, a Django migration is a Python file that describes schema changes as a series of Operation objects. When you run python manage.py makemigrations, Django inspects your current models.py and compares them against your historical state to automatically generate these operations."},{"order":5,"type":"subheading","text":"Writing Custom Schema Operations"},{"order":6,"type":"paragraph","text":"Sometimes built-in operations like AddField or AlterField are not enough. You might need to execute database-specific commands, such as creating a PostgreSQL extension or a complex database view. Django allows you to encapsulate this logic inside a subclass of migrations.Operations."},{"order":7,"type":"code","text":"# operations/create_extension.py
from django.db.migrations.operations.base import Operation

class CreateExtension(Operation):
    reversible = True

    def __init__(self, extension_name):
        self.extension_name = extension_name

    def database_forwards(self, app_label, schema_editor, from_state, to_state):
        if schema_editor.connection.vendor == 'postgresql':
            schema_editor.execute(f"CREATE EXTENSION IF NOT EXISTS \"{self.extension_name}\";")

    def database_backwards(self, app_label, schema_editor, from_state, to_state):
        if schema_editor.connection.vendor == 'postgresql':
            schema_editor.execute(f"DROP EXTENSION IF EXISTS \"{self.extension_name}\";")

    def describe(self):
        return f"Create PostgreSQL extension {self.extension_name}""},{"order":8,"type":"paragraph","text":"To use this custom operation, you import it directly into your migration file and append it to the operations list."},{"order":9,"type":"code","text":"# myapp/migrations/0002_add_uuid_ossp.py
from django.db import migrations
from operations.create_extension import CreateExtension

class Migration(migrations.Migration):
    dependencies = [
        ('myapp', '0001_initial'),
    ]

    operations = [
        CreateExtension('uuid-ossp'),
    ]"},{"order":10,"type":"subheading","text":"Implementing Safe Data Migrations"},{"order":11,"type":"paragraph","text":"Schema changes often require data manipulation. For example, splitting a single 'full_name' field into 'first_name' and 'last_name' fields requires migrating existing records. Never import model classes directly at the top of a migration file, as this references the current state of the model rather than the historical state required for that specific migration step."},{"order":12,"type":"code","text":"# Correct approach for data migrations
from django.db import migrations

def populate_name_fields(apps, schema_editor):
    MyModel = apps.get_model('myapp', 'MyModel')
    for obj in MyModel.objects.all():
        parts = obj.full_name.split(' ', 1)
        obj.first_name = parts[0]
        obj.last_name = parts[1] if len(parts) > 1 else ''
        obj.save(update_fields=['first_name', 'last_name'])

class Migration(migrations.Migration):
    dependencies = [
        ('myapp', '0002_add_first_last_name'),
    ]

    operations = [
        migrations.RunPython(populate_name_fields, reverse_code=migrations.RunPython.noop),
    ]"},{"order":13,"type":"subheading","text":"Best Practices for Production Environments"},{"order":14,"type":"bullet_point","text":"Always test both forward and backward migration paths to ensure reversibility."},{"order":15,"type":"bullet_point","text":"Keep data migrations independent of external services or volatile code bases."},{"order":16,"type":"bullet_point","text":"Use atomic transactions carefully. If a data migration updates millions of rows, disable atomicity by setting atomic = False on the migration class to prevent locking the database for too long."}]
